defmodule Elzoo.InstallConfigurationTest do
  # ELZ-091 (issue #165): the optional `install_configuration` manifest field, its validation and its
  # rendering into the generated install file. Root tests: nothing is copied or compiled here; the
  # copied consumers carry the end-to-end evidence (Elzoo.CureConsumerCase).
  use ExUnit.Case, async: true

  alias Elzoo.{Export, Registry}

  @root File.cwd!()
  @anthropic "integration/ai-text-anthropic"
  @line "config :req_llm, load_dotenv: false"

  # Install files generated by the exporter at the base commit of this change (4e16947), before the
  # field existed. A selection without the field must keep producing these exact bytes; regenerate
  # them only with a reviewed change of the install text or of these providers' pins.
  @golden %{
    "runtime/unit" => "runtime-unit.txt",
    "integration/cure-json" => "integration-cure-json.txt"
  }

  setup do
    destination =
      Path.join(System.tmp_dir!(), "elzoo-install-config-#{System.unique_integer([:positive])}")

    File.mkdir_p!(destination)
    File.write!(Path.join(destination, "mix.exs"), "# consumer\n")
    on_exit(fn -> File.rm_rf!(destination) end)
    {:ok, destination: destination, registry: Registry.load!(@root)}
  end

  defp instructions(plan), do: plan.files[plan.instructions]

  test "a selection without the field exports the base install file byte for byte", ctx do
    for {id, fixture} <- @golden do
      expected = File.read!(Path.join([__DIR__, "fixtures", "install", fixture]))
      plan = Export.plan!(ctx.registry, [id], ctx.destination)
      assert plan.configuration == []
      assert instructions(plan) == expected, "install file of #{id} changed"
    end
  end

  test "only a closure that declares the field gets a Configuration section", ctx do
    ready =
      for {id, entry} <- ctx.registry.entries, entry["status"] == "ready", do: id

    for id <- ready do
      closure = Registry.select!(ctx.registry, [id])
      declared? = Enum.any?(closure, &Map.has_key?(&1, "install_configuration"))
      plan = Export.plan!(ctx.registry, [id], ctx.destination)
      assert instructions(plan) =~ "## Configuration" == declared?, id
      assert plan.configuration != [] == declared?, id
    end
  end

  test "the Anthropic provider's line reaches its install file with its reason", ctx do
    plan = Export.plan!(ctx.registry, [@anthropic], ctx.destination)
    assert plan.configuration == [@line]
    text = instructions(plan)

    assert text =~
             "```elixir\n# integration/ai-text-anthropic: Otherwise req_llm loads a .env file " <>
               "from the working directory when its application starts under Mix.\n#{@line}\n```\n"

    # The receipt is unchanged in shape: it does not take the new key.
    receipt = Jason.decode!(plan.files[plan.receipt])
    refute Enum.any?(receipt["pieces"], &Map.has_key?(&1, "install_configuration"))
  end

  test "an exact duplicate line keeps its first declaration in selection order", ctx do
    registry =
      declare(ctx.registry, "integration/ai-text", [%{"line" => @line, "reason" => "First."}])

    plan = Export.plan!(registry, [@anthropic], ctx.destination)
    assert plan.configuration == [@line]

    assert [%{piece_id: "integration/ai-text", reason: "First."}] = plan.configuration_provenance

    text = instructions(plan)
    assert text =~ "# integration/ai-text: First.\n#{@line}\n"
    refute text =~ "# integration/ai-text-anthropic:"
    assert length(String.split(text, "\n#{@line}\n")) == 2
  end

  test "an identical value for one key across pieces is compatible", ctx do
    registry =
      declare(ctx.registry, "integration/ai-text", [
        %{"line" => "config :req_llm, [load_dotenv: false]", "reason" => "Same value."}
      ])

    plan = Export.plan!(registry, [@anthropic], ctx.destination)
    assert plan.configuration == ["config :req_llm, [load_dotenv: false]", @line]
  end

  test "selected pieces that set one key to different values are refused", ctx do
    registry =
      declare(ctx.registry, "integration/ai-text", [
        %{"line" => "config :req_llm, load_dotenv: true", "reason" => "Disagrees."}
      ])

    message =
      "selected pieces disagree on configuration :req_llm :load_dotenv: integration/ai-text sets " <>
        "true, integration/ai-text-anthropic sets false"

    assert_raise ArgumentError, message, fn ->
      Export.plan!(registry, [@anthropic], ctx.destination)
    end

    refute File.exists?(Path.join(ctx.destination, ".elzoo"))
  end

  test "lines are parsed as data and never evaluated" do
    marker = "elzoo_install_configuration_evaluated"
    System.delete_env(marker)
    line = ~s|config :req_llm, load_dotenv: System.put_env("#{marker}", "1")|
    assert {:error, "values must be literals"} = Registry.configuration_settings(line)
    assert System.get_env(marker) == nil

    assert {:ok, {:req_llm, [load_dotenv: false]}} = Registry.configuration_settings(@line)

    assert {:ok, {:app, [a: nil, b: 1, c: 1.5, d: "s", e: [:x, "y"], f: :atom]}} =
             Registry.configuration_settings(
               ~s|config :app, a: nil, b: 1, c: 1.5, d: "s", e: [:x, "y"], f: :atom|
             )
  end

  test "the registry refuses malformed install configuration", ctx do
    providers = ctx.registry.providers
    base = %{"id" => "x/y", "providers" => ["req_llm", "elixir"]}
    item = fn line -> %{"line" => line, "reason" => "Why."} end

    valid = Map.put(base, "install_configuration", [item.(@line)])
    assert :ok = Registry.validate_install_configuration!(valid, providers)
    assert :ok = Registry.validate_install_configuration!(base, providers)

    refusals = [
      {"not a list", %{"line" => @line, "reason" => "Why."}, ~r/non-empty list/},
      {"empty", [], ~r/non-empty list/},
      {"extra key", [Map.put(item.(@line), "note", "x")], ~r/exactly line and reason/},
      {"missing reason", [%{"line" => @line}], ~r/exactly line and reason/},
      {"empty reason", [%{"line" => @line, "reason" => " "}],
       ~r/missing install_configuration reason/},
      {"not a string", [item.(5)], ~r/missing install_configuration line/},
      {"multi-line", [item.(@line <> "\nconfig :req_llm, x: 1")], ~r/single line required/},
      {"carriage return", [%{"line" => @line, "reason" => "a\rb"}], ~r/single line required/},
      {"function call", [item.(~s|config :req_llm, key: System.get_env("K")|)], ~r/literals/},
      {"variable", [item.("config :req_llm, key: value")], ~r/literals/},
      {"interpolation", [item.(~S|config :req_llm, key: "#{1}"|)], ~r/literals/},
      {"two expressions", [item.(@line <> "; IO.puts(1)")], ~r/single config/},
      {"import", [item.("import Config")], ~r/single config/},
      {"config/3", [item.("config :req_llm, Some.Module, key: 1")], ~r/single config/},
      {"no settings", [item.("config :req_llm, []")], ~r/no settings/},
      {"duplicate key", [item.("config :req_llm, a: 1, a: 2")], ~r/duplicate setting/},
      {"unparseable", [item.("config :req_llm, load_dotenv:")], ~r/does not parse/},
      {"not a declared provider", [item.("config :logger, level: :info")],
       ~r/not a declared provider/},
      {"platform provider", [item.("config :elixir, ansi_enabled: false")],
       ~r/not a declared provider/},
      {"duplicate line", [item.(@line), item.(@line)], ~r/duplicate install_configuration line/}
    ]

    for {_name, field, message} <- refusals do
      piece = Map.put(base, "install_configuration", field)

      assert_raise ArgumentError, message, fn ->
        Registry.validate_install_configuration!(piece, providers)
      end
    end
  end

  defp declare(registry, id, items) do
    update_in(registry, [:entries, id], &Map.put(&1, "install_configuration", items))
  end
end
